from django.test import SimpleTestCase
from unittest.mock import MagicMock, patch


class TestClassonlymethod(SimpleTestCase):
    """Tests for classonlymethod class."""

    def test_classonlymethod_accessible_on_class(self):
        from django.utils.decorators import classonlymethod

        class MyClass:
            @classonlymethod
            def my_method(cls):
                return "class method"

        result = MyClass.my_method()
        self.assertEqual(result, "class method")

    def test_classonlymethod_raises_on_instance_access(self):
        from django.utils.decorators import classonlymethod

        class MyClass:
            @classonlymethod
            def my_method(cls):
                return "class method"

        obj = MyClass()
        with self.assertRaises(AttributeError) as context:
            obj.my_method()
        self.assertIn("available only on the class", str(context.exception))


class TestMethodDecorator(SimpleTestCase):
    """Tests for method_decorator function."""

    def test_method_decorator_on_class_method(self):
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        class MyClass:
            @method_decorator(my_decorator, name='my_method')
            def my_method(self):
                return "result"

        obj = MyClass()
        result = obj.my_method()
        self.assertEqual(result, "result_decorated")

    def test_method_decorator_raises_value_error_invalid_name(self):
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyClass:
            pass

        with self.assertRaises(ValueError) as context:
            @method_decorator(my_decorator, name='nonexistent_method')
            class MyClass2:
                pass
        self.assertIn("name of a method", str(context.exception))

    def test_method_decorator_raises_type_error_non_callable(self):
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyClass:
            non_callable_attr = "not a method"

        # The TypeError is raised when trying to decorate an existing attribute
        # that isn't callable. We need to use a class where the attribute exists.
        with self.assertRaises(TypeError) as context:
            @method_decorator(my_decorator, name='non_callable_attr')
            class MyClass2:
                non_callable_attr = "not a method"
        self.assertIn("isn't a callable attribute", str(context.exception))

    def test_method_decorator_preserves_wrapped_name(self):
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class MyClass:
            @method_decorator(my_decorator, name='my_method')
            def my_method(self):
                return "result"

        # Check that the wrapper preserves the original function's name
        self.assertEqual(MyClass.my_method.__name__, 'my_method')

    def test_method_decorator_with_multiple_decorators(self):
        from django.utils.decorators import method_decorator

        def decorator1(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d1"
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_d2"
            return wrapper

        class MyClass:
            @method_decorator([decorator1, decorator2], name='my_method')
            def my_method(self):
                return "result"

        obj = MyClass()
        result = obj.my_method()
        # Decorators are applied in reverse order (last one first)
        self.assertEqual(result, "result_d2_d1")

    def test_method_decorator_with_iterable_single_decorator(self):
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        class MyClass:
            @method_decorator((my_decorator,), name='my_method')
            def my_method(self):
                return "result"

        obj = MyClass()
        result = obj.my_method()
        self.assertEqual(result, "result_decorated")


