        class DummyMiddleware:
            def __init__(self, view_func, *args, **kwargs):
                self.args = args
                self.kwargs = kwargs

        factory = make_middleware_decorator(DummyMiddleware)
        decorator = factory("arg1", kwarg1="value1")
        self.assertTrue(callable(decorator))

