    def test_middleware_process_template_response_called(self):
        from django.utils.decorators import make_middleware_decorator

        class TemplateResponse:
            def __init__(self, content):
                self.content = content
                self.callbacks = []

            def render(self):
                return self.content

            def add_post_render_callback(self, callback):
                self.callbacks.append(callback)

        class ProcessTemplateResponseMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_template_response(self, request, response):
                return "template_processed"

        factory = make_middleware_decorator(ProcessTemplateResponseMiddleware)
        decorator = factory()

        def view_func(request):
            return TemplateResponse("template_content")

        wrapped = decorator(view_func)
        request = MagicMock()
        result = wrapped(request)
        self.assertEqual(result, "template_processed")


