class TestSyncAsyncMiddlewareMarkers(SimpleTestCase):
    """Tests for sync/async middleware marker functions."""

    def test_sync_and_async_middleware_sets_flags(self):
        from django.utils.decorators import sync_and_async_middleware

        def dummy_factory():
            pass

        decorated = sync_and_async_middleware(dummy_factory)
        self.assertTrue(decorated.sync_capable)
        self.assertTrue(decorated.async_capable)

    def test_sync_only_middleware_sets_flags(self):
        from django.utils.decorators import sync_only_middleware

        def dummy_factory():
            pass

        decorated = sync_only_middleware(dummy_factory)
        self.assertTrue(decorated.sync_capable)
        self.assertFalse(decorated.async_capable)

    def test_async_only_middleware_sets_flags(self):
        from django.utils.decorators import async_only_middleware

        def dummy_factory():
            pass

        decorated = async_only_middleware(dummy_factory)
        self.assertFalse(decorated.sync_capable)
        self.assertTrue(decorated.async_capable)

    def test_decorator_preserves_wrapped_function(self):
        from django.utils.decorators import sync_and_async_middleware

        def original_factory():
            """Original docstring"""
            pass

        decorated = sync_and_async_middleware(original_factory)
        self.assertEqual(decorated.__name__, original_factory.__name__)
        self.assertEqual(decorated.__doc__, original_factory.__doc__)
